import{_ as t,o as a,c as r,a4 as i}from"./chunks/framework.BE47AOxC.js";const v=JSON.parse('{"title":"Version v0.10.0","description":"Notes de la version v0.10.0 de Teuthis-CMS.","frontmatter":{"title":"Version v0.10.0","description":"Notes de la version v0.10.0 de Teuthis-CMS."},"headers":[],"relativePath":"versions/v0-10-0.md","filePath":"versions/v0-10-0.md"}'),o={name:"versions/v0-10-0.md"};function s(n,e,d,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="version-v0-10-0" tabindex="-1">Version v0.10.0 <a class="header-anchor" href="#version-v0-10-0" aria-label="Permalink to &quot;Version v0.10.0&quot;">​</a></h1><p>Publiée le 14 octobre 2026. <a href="https://github.com/Bastien-OC20/calamars/releases/tag/v0.10.0" target="_blank" rel="noreferrer">La release sur GitHub</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Depuis une instance en 0.9.0, ne passez pas en 0.10.0 : passez directement en 0.10.1.</strong> La commande <code>teuthis</code> de la 0.9.0 ne recopie pas le nouveau script de la copie distante ; <code>sudo teuthis mettre-a-jour 0.10.0</code> échoue alors et revient proprement en 0.9.0, sans perte (#22).</p></div><h2 id="v0-10-0-—-2026-10-13" tabindex="-1">v0.10.0 — 2026-10-13 <a class="header-anchor" href="#v0-10-0-—-2026-10-13" aria-label="Permalink to &quot;v0.10.0 — 2026-10-13&quot;">​</a></h2><p>Les sauvegardes quittent enfin le serveur, chiffrées avant l&#39;envoi.</p><h3 id="nouveautes" tabindex="-1">Nouveautés <a class="header-anchor" href="#nouveautes" aria-label="Permalink to &quot;Nouveautés&quot;">​</a></h3><ul><li><strong>Copie distante chiffrée des sauvegardes</strong> (ADR-0070, qui amende l&#39;ADR-0045 et l&#39;ADR-0052) : un service <code>copie-distante</code> (restic) envoie chaque nouvelle sauvegarde vers un stockage <strong>S3 compatible</strong> ou <strong>SFTP</strong>, chiffrée sur le serveur avant de partir — l&#39;hébergeur ne peut pas la lire. Conservation : 7 jours, 4 semaines, 6 mois ; vérification d&#39;intégrité quotidienne d&#39;un dixième du dépôt. <strong>Livré inactif</strong> : rien n&#39;est contacté tant que vous ne l&#39;avez pas configuré. <ul><li><code>sudo teuthis copie-distante configurer</code> : questions, <strong>essai de connexion et d&#39;écriture avant d&#39;enregistrer</strong>, mot de passe du dépôt généré et <strong>affiché une seule fois</strong> — à garder hors du serveur : sans lui, la copie est illisible. Il n&#39;est ni dans le <code>.env</code> ni dans les sauvegardes.</li><li>SFTP : clé SSH dédiée, empreinte de l&#39;hôte vérifiée (jamais acceptée à l&#39;aveugle).</li><li><code>teuthis etat</code> montre la dernière copie et alerte au-delà de 26 h ; une copie en échec rend <code>sauvegarde</code> et <code>copie-distante</code> <em>unhealthy</em>.</li><li><strong>Serveur perdu</strong> : réinstaller la même version, <code>teuthis copie-distante configurer --mot-de-passe-existant</code>, puis <code>teuthis restaurer --distante dernier --avec-pile</code> (<code>deploy/LISEZMOI.md</code>, « Serveur perdu »).</li></ul></li></ul><h3 id="corrections" tabindex="-1">Corrections <a class="header-anchor" href="#corrections" aria-label="Permalink to &quot;Corrections&quot;">​</a></h3><ul><li><code>teuthis etat</code> affichait un âge négatif (« il y a -1 h ») pour une sauvegarde récente : le nom de la sauvegarde est désormais lu dans le fuseau de la pile (#19).</li></ul><h3 id="a-faire-par-l-exploitant" tabindex="-1">À faire par l&#39;exploitant <a class="header-anchor" href="#a-faire-par-l-exploitant" aria-label="Permalink to &quot;À faire par l&#39;exploitant&quot;">​</a></h3><ul><li><strong>Mettre à jour</strong> : <code>sudo teuthis mettre-a-jour 0.10.0</code>. Aucune migration de base, aucune variable obligatoire nouvelle. Un service s&#39;ajoute (<code>copie-distante</code>, inactif) : l&#39;image <code>restic/restic</code> est téléchargée et vérifiée par son empreinte.</li><li><strong>Configurer la copie distante</strong> (recommandé) : <code>sudo teuthis copie-distante configurer</code>, puis <strong>notez le mot de passe affiché hors du serveur</strong>.</li></ul>',11)])])}const h=t(o,[["render",s]]);export{v as __pageData,h as default};
